-- RestaurantAnalysis: du lieu duoc xuat truc tiep tu SQL Server.
-- 1.210 quan, 17 cot; giu Unicode tieng Viet va gia VND cho hai nguoi.
-- Phan III report: Step 0 va Query 3.1-3.4 o cuoi file.
-- Mo hinh report: dbo.Location + dbo.Restaurant + dbo.Review.
-- dbo.SQL_dim_restaurants JOIN ba bang de chay Query 3.1-3.4.
-- Bang goc dbo.hanoi_restaurants_cleaned duoc giu de bao toan du lieu.
-- Ket qua duoc tinh lai tu du lieu, khong gan cung so trong report.
-- Mo file nay bang SSMS, ket noi SQL Server, sau do Execute (F5).
-- Neu database chua co, script tao RestaurantAnalysis.
-- Neu bang da ton tai, giu nguyen bang va du lieu; khong chen trung, khong DROP.
-- Notebook: SERVER=localhost; DATABASE=RestaurantAnalysis;
--           dbo.Restaurant JOIN dbo.Location JOIN dbo.Review; Windows Authentication.

USE [master];
GO
IF DB_ID(N'RestaurantAnalysis') IS NULL
    EXEC(N'CREATE DATABASE [RestaurantAnalysis]');
GO
USE [RestaurantAnalysis];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
    BEGIN TRANSACTION;
    IF OBJECT_ID(N'dbo.hanoi_restaurants_cleaned', N'U') IS NULL
    BEGIN
CREATE TABLE [dbo].[hanoi_restaurants_cleaned] (
    [Restaurant_ID] nvarchar(50) NOT NULL,
    [Restaurant_Name] nvarchar(50) NOT NULL,
    [Address] nvarchar(100) NOT NULL,
    [Locality] nvarchar(50) NOT NULL,
    [Locality_Verbose] nvarchar(50) NOT NULL,
    [Cuisines] nvarchar(50) NOT NULL,
    [Average_Cost_for_two] int NOT NULL,
    [Currency] nvarchar(50) NOT NULL,
    [Has_Table_booking] bit NOT NULL,
    [Has_Online_delivery] bit NOT NULL,
    [Is_delivering_now] bit NOT NULL,
    [Price_range] tinyint NOT NULL,
    [Aggregate_rating] float(53) NOT NULL,
    [Rating_text] nvarchar(50) NOT NULL,
    [Votes] smallint NOT NULL,
    [latitude] float(53) NOT NULL,
    [longitude] float(53) NOT NULL,
    CONSTRAINT [PK_hanoi_restaurants_cleaned] PRIMARY KEY ([Restaurant_ID])
);





        PRINT N'Da tao bang va nap 1210 quan.';
    END
    ELSE
        PRINT N'Bang da ton tai: giu nguyen du lieu, khong nhap lai.';
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO

-- Kiem tra du lieu va pham vi cum Hoa Lac trong bao cao.
SELECT COUNT(*) AS so_quan, COUNT(DISTINCT Restaurant_ID) AS so_ma_duy_nhat
FROM dbo.hanoi_restaurants_cleaned;

SELECT CASE WHEN Locality IN
    (N'Hòa Lạc', N'Thạch Hòa', N'Tân Xã', N'Bắc Phú Cát', N'Thạch Thất',
     N'Liên Quan', N'Tây Phương', N'Yên Bình', N'Bình Yên', N'Phú Cát')
    THEN N'Cụm Hòa Lạc' ELSE N'Nội thành' END AS khu_vuc,
    COUNT(*) AS so_quan
FROM dbo.hanoi_restaurants_cleaned
GROUP BY CASE WHEN Locality IN
    (N'Hòa Lạc', N'Thạch Hòa', N'Tân Xã', N'Bắc Phú Cát', N'Thạch Thất',
     N'Liên Quan', N'Tây Phương', N'Yên Bình', N'Bình Yên', N'Phú Cát')
    THEN N'Cụm Hòa Lạc' ELSE N'Nội thành' END;
GO

-- ================================================================
-- PHAN III - SQL ANALYSIS (cung ten cot va cong thuc voi report)
-- Step 0: chuyen nguon 17 cot thanh Location, Restaurant, Review.
-- CHECK/FK/index tren cac bang; VIEW JOIN dung chung cho Query 3.1-3.4.
-- Giu staging goc, chi INSERT dong thieu; du lieu khac thi THROW, khong ghi de.
-- ================================================================
SET XACT_ABORT ON;
BEGIN TRY
    BEGIN TRANSACTION;
    IF OBJECT_ID(N'dbo.SQL_dim_restaurants') IS NOT NULL
       AND OBJECT_ID(N'dbo.SQL_dim_restaurants', N'V') IS NULL
        THROW 50001, N'dbo.SQL_dim_restaurants da ton tai va khong phai VIEW. Kiem tra truoc khi tiep tuc; khong ghi de du lieu.', 1;

    IF OBJECT_ID(N'dbo.CK_hanoi_cost', N'C') IS NULL
        ALTER TABLE dbo.hanoi_restaurants_cleaned WITH CHECK
        ADD CONSTRAINT CK_hanoi_cost CHECK (Average_Cost_for_two > 0);
    IF OBJECT_ID(N'dbo.CK_hanoi_rating', N'C') IS NULL
        ALTER TABLE dbo.hanoi_restaurants_cleaned WITH CHECK
        ADD CONSTRAINT CK_hanoi_rating CHECK (Aggregate_rating BETWEEN 0 AND 5);
    IF OBJECT_ID(N'dbo.CK_hanoi_votes', N'C') IS NULL
        ALTER TABLE dbo.hanoi_restaurants_cleaned WITH CHECK
        ADD CONSTRAINT CK_hanoi_votes CHECK (Votes >= 0);
    IF OBJECT_ID(N'dbo.CK_hanoi_price_range', N'C') IS NULL
        ALTER TABLE dbo.hanoi_restaurants_cleaned WITH CHECK
        ADD CONSTRAINT CK_hanoi_price_range CHECK (Price_range BETWEEN 1 AND 4);
    IF OBJECT_ID(N'dbo.CK_hanoi_gps', N'C') IS NULL
        ALTER TABLE dbo.hanoi_restaurants_cleaned WITH CHECK
        ADD CONSTRAINT CK_hanoi_gps CHECK
            (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180);
    IF OBJECT_ID(N'dbo.CK_hanoi_currency', N'C') IS NULL
        ALTER TABLE dbo.hanoi_restaurants_cleaned WITH CHECK
        ADD CONSTRAINT CK_hanoi_currency CHECK (Currency = N'VND');

    IF NOT EXISTS (SELECT 1 FROM sys.indexes
                   WHERE object_id = OBJECT_ID(N'dbo.hanoi_restaurants_cleaned')
                     AND name = N'IX_hanoi_locality_analysis')
        CREATE NONCLUSTERED INDEX IX_hanoi_locality_analysis
        ON dbo.hanoi_restaurants_cleaned (Locality)
        INCLUDE (Average_Cost_for_two, Aggregate_rating, Votes,
                 Has_Table_booking, Has_Online_delivery, Price_range, Cuisines);

    -- Data dictionary: TEXT -> NVARCHAR/VARCHAR; GPS REAL trong SQL Server.
    -- location_id la surrogate key noi bo, KHONG phai ma hanh chinh.
    -- Thu tu BIN2 co dinh de cung locality luon co cung ID trong file nay.
    IF EXISTS (SELECT 1 FROM dbo.hanoi_restaurants_cleaned
               GROUP BY Locality HAVING COUNT(DISTINCT Locality_Verbose) <> 1)
        THROW 50002, N'Mot locality co nhieu locality_verbose; can kiem tra du lieu nguon.', 1;

    IF OBJECT_ID(N'dbo.Location', N'U') IS NULL
        CREATE TABLE dbo.Location (
            location_id INT NOT NULL CONSTRAINT PK_Location PRIMARY KEY,
            locality NVARCHAR(50) NOT NULL CONSTRAINT UQ_Location_locality UNIQUE,
            locality_verbose NVARCHAR(50) NOT NULL
        );
    IF OBJECT_ID(N'dbo.Restaurant', N'U') IS NULL
        CREATE TABLE dbo.Restaurant (
            restaurant_id NVARCHAR(50) NOT NULL CONSTRAINT PK_Restaurant PRIMARY KEY,
            restaurant_name NVARCHAR(50) NOT NULL,
            location_id INT NOT NULL,
            address NVARCHAR(100) NOT NULL,
            cuisines NVARCHAR(50) NOT NULL,
            average_cost_for_two INT NOT NULL,
            currency NVARCHAR(50) NOT NULL,
            has_table_booking VARCHAR(3) NOT NULL,
            has_online_delivery VARCHAR(3) NOT NULL,
            is_delivering_now VARCHAR(3) NOT NULL,
            latitude REAL NOT NULL,
            longitude REAL NOT NULL,
            price_range INT NOT NULL,
            CONSTRAINT FK_Restaurant_Location FOREIGN KEY (location_id)
                REFERENCES dbo.Location(location_id),
            CONSTRAINT CK_Restaurant_cost CHECK (average_cost_for_two > 0),
            CONSTRAINT CK_Restaurant_currency CHECK (currency = N'VND'),
            CONSTRAINT CK_Restaurant_booking CHECK (has_table_booking IN ('Yes', 'No')),
            CONSTRAINT CK_Restaurant_delivery CHECK (has_online_delivery IN ('Yes', 'No')),
            CONSTRAINT CK_Restaurant_delivering CHECK (is_delivering_now IN ('Yes', 'No')),
            CONSTRAINT CK_Restaurant_price_range CHECK (price_range BETWEEN 1 AND 4),
            CONSTRAINT CK_Restaurant_gps CHECK
                (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)
        );
    -- CSV chi co danh gia tong hop; mot dong Review cho moi restaurant,
    -- khong tao review ca nhan khong co trong du lieu.
    IF OBJECT_ID(N'dbo.Review', N'U') IS NULL
        CREATE TABLE dbo.Review (
            restaurant_id NVARCHAR(50) NOT NULL CONSTRAINT PK_Review PRIMARY KEY,
            aggregate_rating FLOAT(53) NOT NULL,
            rating_text NVARCHAR(50) NOT NULL,
            votes SMALLINT NOT NULL,
            CONSTRAINT FK_Review_Restaurant FOREIGN KEY (restaurant_id)
                REFERENCES dbo.Restaurant(restaurant_id),
            CONSTRAINT CK_Review_rating CHECK (aggregate_rating BETWEEN 0 AND 5),
            CONSTRAINT CK_Review_votes CHECK (votes >= 0)
        );

    SELECT CAST(DENSE_RANK() OVER (ORDER BY Locality COLLATE Latin1_General_100_BIN2) AS INT) AS location_id,
           Locality AS locality, MIN(Locality_Verbose) AS locality_verbose
    INTO #SourceLocation
    FROM dbo.hanoi_restaurants_cleaned
    GROUP BY Locality;
    IF EXISTS (SELECT 1 FROM dbo.Location l
               WHERE NOT EXISTS (SELECT 1 FROM #SourceLocation s WHERE s.locality = l.locality))
       OR EXISTS (SELECT 1 FROM dbo.Restaurant r
                  WHERE NOT EXISTS (SELECT 1 FROM dbo.hanoi_restaurants_cleaned s
                                    WHERE s.Restaurant_ID = r.restaurant_id))
       OR EXISTS (SELECT 1 FROM dbo.Review t
                  WHERE NOT EXISTS (SELECT 1 FROM dbo.hanoi_restaurants_cleaned s
                                    WHERE s.Restaurant_ID = t.restaurant_id))
        THROW 50005, N'Bang chuan hoa chua du lieu ngoai nguon; khong xoa hay ghi de. Can kiem tra database.', 1;
    IF EXISTS (SELECT 1 FROM #SourceLocation s JOIN dbo.Location l
               ON l.location_id = s.location_id OR l.locality = s.locality
               WHERE l.location_id <> s.location_id OR l.locality <> s.locality
                  OR l.locality_verbose <> s.locality_verbose)
        THROW 50003, N'Location da ton tai khac mapping nguon; khong ghi de du lieu.', 1;
    SELECT s.location_id, s.locality, s.locality_verbose
    FROM #SourceLocation s
    WHERE NOT EXISTS (SELECT 1 FROM dbo.Location l WHERE l.location_id = s.location_id);

         average_cost_for_two, currency, has_table_booking, has_online_delivery,
         is_delivering_now, latitude, longitude, price_range)
    SELECT s.Restaurant_ID, s.Restaurant_Name, l.location_id, s.Address, s.Cuisines,
           s.Average_Cost_for_two, s.Currency,
           CASE WHEN s.Has_Table_booking = 1 THEN 'Yes' ELSE 'No' END,
           CASE WHEN s.Has_Online_delivery = 1 THEN 'Yes' ELSE 'No' END,
           CASE WHEN s.Is_delivering_now = 1 THEN 'Yes' ELSE 'No' END,
           s.latitude, s.longitude, s.Price_range
    FROM dbo.hanoi_restaurants_cleaned s
    JOIN #SourceLocation l ON l.locality = s.Locality
    WHERE NOT EXISTS (SELECT 1 FROM dbo.Restaurant r WHERE r.restaurant_id = s.Restaurant_ID);
    SELECT s.Restaurant_ID, s.Aggregate_rating, s.Rating_text, s.Votes
    FROM dbo.hanoi_restaurants_cleaned s
    WHERE NOT EXISTS (SELECT 1 FROM dbo.Review t WHERE t.restaurant_id = s.Restaurant_ID);

    -- Neu bang dich da co du lieu khac thi dung va rollback, khong UPDATE ep khop.
    IF EXISTS (
        SELECT s.Restaurant_ID, s.Restaurant_Name, l.location_id, s.Address, s.Cuisines,
               s.Average_Cost_for_two, s.Currency,
               CASE WHEN s.Has_Table_booking = 1 THEN 'Yes' ELSE 'No' END,
               CASE WHEN s.Has_Online_delivery = 1 THEN 'Yes' ELSE 'No' END,
               CASE WHEN s.Is_delivering_now = 1 THEN 'Yes' ELSE 'No' END,
               CAST(s.latitude AS REAL), CAST(s.longitude AS REAL), CAST(s.Price_range AS INT)
        FROM dbo.hanoi_restaurants_cleaned s
        JOIN #SourceLocation l ON l.locality = s.Locality
        EXCEPT
        SELECT restaurant_id, restaurant_name, location_id, address, cuisines,
               average_cost_for_two, currency, has_table_booking, has_online_delivery,
               is_delivering_now, latitude, longitude, price_range
        FROM dbo.Restaurant
    ) OR EXISTS (
        SELECT Restaurant_ID, Aggregate_rating, Rating_text, Votes
        FROM dbo.hanoi_restaurants_cleaned
        EXCEPT
        SELECT restaurant_id, aggregate_rating, rating_text, votes FROM dbo.Review
    )
        THROW 50004, N'Restaurant/Review da co du lieu khac nguon; khong ghi de. Kiem tra truoc khi dong bo.', 1;
    DROP TABLE #SourceLocation;

    IF NOT EXISTS (SELECT 1 FROM sys.indexes
                   WHERE object_id = OBJECT_ID(N'dbo.Restaurant')
                     AND name = N'IX_Restaurant_location_analysis')
        CREATE NONCLUSTERED INDEX IX_Restaurant_location_analysis
        ON dbo.Restaurant (location_id)
        INCLUDE (average_cost_for_two, has_table_booking, has_online_delivery,
                 price_range, cuisines);

    -- View phan tich: co ten gia day du theo dictionary va alias cu theo Query III.
    EXEC(N'CREATE OR ALTER VIEW dbo.SQL_dim_restaurants AS
        SELECT r.restaurant_id, r.restaurant_name, r.location_id,
               r.address, l.locality, l.locality_verbose, r.cuisines,
               r.average_cost_for_two,
               r.average_cost_for_two AS avg_cost_for_two,
               r.currency, r.has_table_booking, r.has_online_delivery,
               r.is_delivering_now, r.price_range,
               t.aggregate_rating, t.rating_text, t.votes, r.latitude, r.longitude
        FROM dbo.Restaurant r
        JOIN dbo.Location l ON l.location_id = r.location_id
        JOIN dbo.Review t ON t.restaurant_id = r.restaurant_id;');
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO

-- Query 3.1: So quan, thi phan, gia, rating, votes theo 22 khu vuc.
-- Thi phan = so quan khu vuc / tong so quan * 100.
-- Excellent rate = so quan rating >= 4.5 / so quan khu vuc * 100.
DECLARE @TotalCityStores FLOAT = (SELECT COUNT(*) FROM dbo.SQL_dim_restaurants);
SELECT locality AS [Area],
       COUNT(restaurant_id) AS [Store Count],
       ROUND(COUNT(restaurant_id) * 100.0 / NULLIF(@TotalCityStores, 0), 2) AS [Market Share (%)],
       ROUND(AVG(CAST(avg_cost_for_two AS FLOAT)), 0) AS [Avg Cost for 2 (VND)],
       ROUND(AVG(aggregate_rating), 2) AS [Avg Rating],
       ROUND(AVG(CAST(votes AS FLOAT)), 1) AS [Avg Votes per Store],
       ROUND(SUM(CASE WHEN aggregate_rating >= 4.5 THEN 1.0 ELSE 0.0 END)
             * 100.0 / COUNT(*), 2) AS [Excellent Store Rate (%)]
FROM dbo.SQL_dim_restaurants
GROUP BY locality
ORDER BY [Store Count] DESC;
GO

-- Query 3.2a: Ty le dich vu = so quan co dich vu / so quan khu vuc * 100.
-- Bang Restaurant luu Yes/No dung dictionary, nen truy van report chay truc tiep.
SELECT locality AS [Area],
       COUNT(*) AS [Store Count],
       ROUND(SUM(CASE WHEN has_online_delivery = 'Yes' THEN 1.0 ELSE 0.0 END)
             * 100.0 / COUNT(*), 1) AS [Online Delivery Rate (%)],
       ROUND(SUM(CASE WHEN has_table_booking = 'Yes' THEN 1.0 ELSE 0.0 END)
             * 100.0 / COUNT(*), 1) AS [Table Booking Rate (%)],
       ROUND(AVG(CAST(votes AS FLOAT)), 1) AS [Avg Votes]
FROM dbo.SQL_dim_restaurants
GROUP BY locality
ORDER BY [Store Count] DESC;
GO

-- Query 3.2b: Moi dong la mot to hop price tier / booking / delivery.
-- Khong gop Yes/No de tranh khac ket qua GROUP BY trong report.
SELECT price_range AS [Price Tier],
       has_table_booking AS [Table Booking],
       has_online_delivery AS [Online Delivery],
       COUNT(*) AS [Store Count],
       ROUND(AVG(CAST(avg_cost_for_two AS FLOAT)), 0) AS [Avg Cost for 2 (VND)],
       ROUND(AVG(aggregate_rating), 2) AS [Avg Rating],
       ROUND(AVG(CAST(votes AS FLOAT)), 1) AS [Avg Votes]
FROM dbo.SQL_dim_restaurants
GROUP BY price_range, has_table_booking, has_online_delivery
ORDER BY [Price Tier] DESC, [Avg Votes] DESC;
GO

-- Query 3.3: MCDA; trong so demand 35, quality 30, spending 20,
-- low competition 15. Chuan hoa bang MAX cua tat ca 22 khu vuc.
-- Tinh tren gia tri chua lam tron; chi ROUND ket qua hien thi.
WITH LocalityMetrics AS (
    SELECT locality, COUNT(*) AS store_count,
           AVG(CAST(votes AS FLOAT)) AS avg_votes,
           AVG(CAST(aggregate_rating AS FLOAT)) AS avg_rating,
           AVG(CAST(avg_cost_for_two AS FLOAT)) AS avg_cost
    FROM dbo.SQL_dim_restaurants
    GROUP BY locality
), CityBenchmark AS (
    SELECT MAX(avg_votes) AS max_votes, MAX(avg_rating) AS max_rating,
           MAX(avg_cost) AS max_cost, MAX(store_count) AS max_stores
    FROM LocalityMetrics
)
SELECT m.locality AS [Area], m.store_count AS [Store Count],
       ROUND(m.avg_votes / NULLIF(b.max_votes, 0) * 35.0, 2) AS [Demand Score (35 pts)],
       ROUND(m.avg_rating / NULLIF(b.max_rating, 0) * 30.0, 2) AS [Quality Score (30 pts)],
       ROUND(m.avg_cost / NULLIF(b.max_cost, 0) * 20.0, 2) AS [Spending Score (20 pts)],
       ROUND((1.0 - CAST(m.store_count AS FLOAT) / NULLIF(b.max_stores, 0)) * 15.0, 2) AS [Low-Competition Score (15 pts)],
       ROUND(m.avg_votes / NULLIF(b.max_votes, 0) * 35.0
           + m.avg_rating / NULLIF(b.max_rating, 0) * 30.0
           + m.avg_cost / NULLIF(b.max_cost, 0) * 20.0
           + (1.0 - CAST(m.store_count AS FLOAT) / NULLIF(b.max_stores, 0)) * 15.0, 2) AS [Total Potential Score]
FROM LocalityMetrics AS m
CROSS JOIN CityBenchmark AS b
ORDER BY [Total Potential Score] DESC;
GO

-- Query 3.4a: Nhom am thuc co >= 20 quan, xep theo votes trung binh.
-- Giu nguyen to hop cuisines (khong tach thanh tung mon an).
SELECT cuisines AS [Cuisine Group], COUNT(*) AS [Citywide Store Count],
       ROUND(AVG(CAST(votes AS FLOAT)), 1) AS [Citywide Avg Votes],
       ROUND(AVG(aggregate_rating), 2) AS [Avg Rating]
FROM dbo.SQL_dim_restaurants
GROUP BY cuisines
HAVING COUNT(*) >= 20
ORDER BY [Citywide Avg Votes] DESC;
GO

-- Query 3.4b: Cung am thuc trong khu vuc muc tieu; report dung Long Bien.
SELECT locality AS [Area], cuisines AS [Cuisine Group], COUNT(*) AS [Existing Stores]
FROM dbo.SQL_dim_restaurants
WHERE locality = N'Long Biên'
GROUP BY locality, cuisines
ORDER BY [Existing Stores] DESC;
GO

-- Luu y: cac bang so lieu 3.2a, 3.2b va MCDA trong report cu can
-- cap nhat theo ket qua thuc te o tren; khong sua du lieu de ep khop report.
